using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using UnityEngine;using UnityEngine.InputSystem;using AstroGateway.Stage08B;
namespace AstroGateway.NativeSlice {
 [DefaultExecutionOrder(-100)]public class NativeSliceGame:MonoBehaviour {public MarsPrototype prototype;public MissionRegistry registry;public ControlModeManager modes;public AdaptiveTouch touch;public Transform seat;public float battery=100,health=100,astronautHealth=100; public readonly System.Collections.Generic.List<string> inventory=new System.Collections.Generic.List<string>();public long tick;public readonly TelemetryHistory telemetry=new TelemetryHistory();public readonly System.Collections.Generic.List<ScientificScan> scans=new System.Collections.Generic.List<ScientificScan>();public string notice="",testSave;Transform originalParent;float sampleTime;public bool initialized,testing;
 string SavePath=>string.IsNullOrEmpty(testSave)?Path.Combine(Application.persistentDataPath,"AstroGateway_NativeSlice_v1.json"):testSave;
 void Start(){originalParent=prototype.astronaut.transform.parent;prototype.testControl=true;if(prototype.hud)prototype.hud.gameObject.SetActive(false);if(prototype.mobile){prototype.mobile.Clear();prototype.mobile.enabled=false;}modes.Switch(ControlMode.Astronaut);initialized=true;}
 void Update(){if(!initialized)return;NativeInput input=default;if(!testing){touch.Poll();input=touch.input;var k=Keyboard.current;var m=Mouse.current;if(k!=null&&!k.leftMetaKey.isPressed&&!k.leftCtrlKey.isPressed){input.movement+=new Vector2((k.dKey.isPressed?1:0)-(k.aKey.isPressed?1:0),(k.wKey.isPressed?1:0)-(k.sKey.isPressed?1:0));input.run|=k.leftShiftKey.isPressed;input.brake|=k.spaceKey.isPressed;if(k.digit1Key.wasPressedThisFrame)prototype.SetWeather(0);if(k.digit2Key.wasPressedThisFrame)prototype.SetWeather(1);if(k.digit3Key.wasPressedThisFrame)prototype.SetWeather(2);if(k.eKey.wasPressedThisFrame)Interact();if(k.kKey.wasPressedThisFrame)Scan();}if(m!=null&&m.rightButton.isPressed)input.look+=m.delta.ReadValue();modes.Submit(input);}ApplyInput();if(prototype.driving)battery=Mathf.Max(0,battery-Time.deltaTime*.04f);sampleTime+=Time.deltaTime;if(sampleTime>=1){sampleTime-=1;tick++;Publish();}}
 public void ApplyInput(){var input=modes.Input;prototype.testMove=Vector2.ClampMagnitude(input.movement,1);if(prototype.driving&&input.accelerate)prototype.testMove=new Vector2(prototype.testMove.x,1);prototype.testLook=input.look;prototype.testRun=input.run;prototype.testBrake=input.brake||prototype.driving&&battery<=0;}
 public bool Interact(){bool was=prototype.driving;var astronaut=prototype.astronaut;if(!was){if(battery<=0||health<=0)return false;if(!prototype.Interact())return false;astronaut.enabled=false;if(prototype.animator){prototype.animator.SetFloat("Speed",0);prototype.animator.SetBool("Running",false);}astronaut.transform.SetParent(seat,false);astronaut.transform.localPosition=Vector3.zero;astronaut.gameObject.SetActive(true);modes.Switch(ControlMode.Rover);return true;}astronaut.transform.SetParent(originalParent,true);if(!prototype.Interact()){astronaut.transform.SetParent(seat,true);return false;}if(Physics.Raycast(astronaut.transform.position+Vector3.up*2,Vector3.down,out var ground,8,1<<0,QueryTriggerInteraction.Ignore))astronaut.transform.position=ground.point+Vector3.up*.05f;astronaut.enabled=true;modes.Switch(ControlMode.Astronaut);return true;}
 public void Publish(){telemetry.Record("rover.battery","rover.local",battery,"simulation_percent",tick);telemetry.Record("rover.speed","rover.local",prototype.driving?Mathf.Abs(prototype.speed):0,"m/s",tick);telemetry.Record("rover.health","rover.local",health,"simulation_percent",tick);telemetry.Record("astronaut.oxygen","astronaut.local",prototype.oxygen,"simulation_percent",tick);}
 public bool Scan(){if(scans.Count>=32||modes.Mode==ControlMode.Menu)return false;scans.Add(new ScientificScan{sampleId=Guid.NewGuid().ToString(),location=prototype.ActivePosition(),tick=tick,syntheticIndex=(scans.Count%7)/7f});notice="Simulated scan recorded; not NASA observational data.";return true;}
 static bool Percent(float v)=>!float.IsNaN(v)&&!float.IsInfinity(v)&&v>=0&&v<=100;
 static bool Position(Vector3 v)=>!float.IsNaN(v.x)&&!float.IsNaN(v.y)&&!float.IsNaN(v.z)&&Mathf.Abs(v.x)<=119&&Mathf.Abs(v.z)<=119&&v.y>=-20&&v.y<=80;
 public Rect DataPanel {get{var safe=Screen.safeArea;float width=Mathf.Min(410,safe.width-24);return new Rect(safe.xMax-width-12,Screen.height-safe.yMax+12,width,375);}}
 public SliceSnapshot CaptureSnapshot()=>new SliceSnapshot{missionId=registry.missionId,astronaut=prototype.astronaut.transform.position,rover=prototype.rover.transform.position,driving=prototype.driving,oxygen=prototype.oxygen,power=prototype.power,battery=battery,health=health,tick=tick,scans=scans.ToList()};
 public bool ValidSnapshot(SliceSnapshot s)=>s!=null&&s.version==1&&s.missionId==registry.missionId&&Position(s.astronaut)&&Position(s.rover)&&Percent(s.oxygen)&&Percent(s.power)&&Percent(s.battery)&&Percent(s.health)&&s.tick>=0&&s.tick<=1000000000&&s.scans!=null&&s.scans.Count<=32&&!s.scans.Any(x=>x==null||!Position(x.location)||x.tick<0||!Percent(x.syntheticIndex)||!Guid.TryParse(x.sampleId,out _)||x.syntheticIndex>1||x.tick>s.tick||x.type!="simulated_surface_scan"||x.instrument!="prototype.synthetic_scanner"||x.analysis!="unverified_simulated")&&s.scans.Select(x=>x.sampleId).Distinct().Count()==s.scans.Count;
 public bool RestoreSnapshot(SliceSnapshot s){if(!ValidSnapshot(s))return false;try{
 if(prototype.driving){prototype.speed=0;if(!Interact())return false;}prototype.rover.enabled=false;prototype.rover.transform.position=s.rover;prototype.rover.enabled=true;prototype.astronaut.enabled=false;prototype.astronaut.transform.position=s.astronaut;prototype.astronaut.enabled=true;Physics.SyncTransforms();if(s.driving&&!Interact())return false;prototype.oxygen=s.oxygen;prototype.power=s.power;battery=s.battery;health=s.health;tick=s.tick;prototype.speed=0;scans.Clear();scans.AddRange(s.scans);Publish();notice="Local snapshot restored; session/witness state remains provisional.";return true;}catch{notice="Snapshot invalid or unavailable.";return false;}}
 public bool Save(){try{Directory.CreateDirectory(Path.GetDirectoryName(SavePath));string tmp=SavePath+".tmp";File.WriteAllText(tmp,JsonUtility.ToJson(CaptureSnapshot()));if(File.Exists(SavePath))File.Replace(tmp,SavePath,null);else File.Move(tmp,SavePath);notice="Separate local snapshot saved.";return true;}catch{notice="Local save unavailable.";return false;}}
 public bool Load(){try{if(!File.Exists(SavePath)||new FileInfo(SavePath).Length>65536)return false;return RestoreSnapshot(JsonUtility.FromJson<SliceSnapshot>(File.ReadAllText(SavePath)));}catch{notice="Snapshot invalid or unavailable.";return false;}}
 public string Export(string folder){Directory.CreateDirectory(folder);string path=Path.Combine(folder,"AstroGateway_Simulated_Scans.json");File.WriteAllText(path,JsonUtility.ToJson(new SliceSnapshot{version=1,missionId=registry.missionId,scans=scans.ToList()}));var b=new StringBuilder("sample_id,x_m,y_m,z_m,tick,synthetic_index,quality\n");foreach(var s in scans)b.AppendLine(string.Join(",",s.sampleId,s.location.x.ToString(CultureInfo.InvariantCulture),s.location.y.ToString(CultureInfo.InvariantCulture),s.location.z.ToString(CultureInfo.InvariantCulture),s.tick,s.syntheticIndex.ToString(CultureInfo.InvariantCulture),"unverified_simulated"));File.WriteAllText(Path.Combine(folder,"AstroGateway_Simulated_Scans.csv"),b.ToString());File.WriteAllText(Path.Combine(folder,"AstroGateway_Simulated_Telemetry.json"),JsonUtility.ToJson(new TelemetryExport{fields=telemetry.records.ToArray()}));return path;}
 void OnGUI(){GUILayout.BeginArea(DataPanel,GUI.skin.box);GUILayout.Label(registry?registry.displayName:"Native control slice");GUILayout.Label("MODE "+(modes?modes.Mode.ToString():"initializing"));GUILayout.Label($"ROVER battery {battery:F1}%  health {health:F1}%  speed {(prototype?Mathf.Abs(prototype.speed):0):F1} m/s");GUILayout.Label("SIMULATED / PROVISIONAL / local only");GUILayout.Label(prototype?$"Oxygen {prototype.oxygen:F1}% / suit power {prototype.power:F1}% / {prototype.WeatherName}":"");if(GUILayout.Button("Scan [K]"))Scan();if(GUILayout.Button("Save local snapshot"))Save();if(GUILayout.Button("Load local snapshot"))Load();if(GUILayout.Button("Export local JSON / CSV")){try{notice=Export(Path.Combine(Application.persistentDataPath,"NativeSliceExports"));}catch{notice="Export unavailable.";}}GUILayout.Label(prototype?prototype.objective:"");GUILayout.Label("Mission data scans: "+scans.Count);if(scans.Count>0){var s=scans[scans.Count-1];GUILayout.Label(s.type+" / tick "+s.tick+" / synthetic index "+s.syntheticIndex.ToString("F2"));}GUILayout.Label(notice);GUILayout.EndArea();}
 }
}
